const __pageData = JSON.parse('{"title":"RAG入门与文档加载切分","description":"大模型的三个局限与 RAG 的六个环节，文档加载器（Document 对象、txt/csv/json/pdf/word/markdown/html）与文档切分器（五种策略、四种实现、chunk 参数与实测）","frontmatter":{"title":"RAG入门与文档加载切分","published":"2026-09-21T00:00:00.000Z","description":"大模型的三个局限与 RAG 的六个环节，文档加载器（Document 对象、txt/csv/json/pdf/word/markdown/html）与文档切分器（五种策略、四种实现、chunk 参数与实测）","tags":["LangChain","AI"],"image":"https://img.tsh520.cn/file/blog/post-covers/langchain-24-rag-basics.webp","order":24,"date":"2026-09-21T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/LangChain学习笔记/24-RAG入门与文档加载切分.md","filePath":"posts/学习文档/LangChain学习笔记/24-RAG入门与文档加载切分.md"}');
